// CertificatePayloadV2 is selected only by a genuine persisted native report
// variant. Archived V1 assembly is unchanged. This participant assembly NEVER
// reads/appends document MetadataRedactionReport or forensic original payloads.
// Prefix and manifest are generated by existing native certificate owners; this
// pure formatter grants no authority to supply arbitrary participant HTML.
func CertificatePayloadV2(prefix string, doc *generated.Document, fields []*generated.DocumentField, claims CertificateEvidenceClaimsV1, manifestHTML *string) (string, error) {
	if len(prefix) > MaxCertificatePayloadBytesV1 || len(fields) > MaxParticipantReportRowsV1 || !reportInputBytesV2(reflect.ValueOf(claims), new(int)) || (manifestHTML != nil && len(*manifestHTML) > MaxCertificatePayloadBytesV1) {
		return "", errors.Join(ErrParticipantReportV1, ErrCertificatePayloadCapacityV1)
	}
	if doc == nil || !utf8.ValidString(prefix) || (claims.ParticipantReportSchema != ParticipantReportSchemaV2 && claims.ParticipantReportSchema != ParticipantReportSchemaV3) || claims.ParticipantReportHTML == "" || claims.DocumentID != doc.ID.String() || claims.OrgID != doc.OrgID.String() || claims.DocumentEventsScope != documentEventsScopeCeremonyRoot {
		return "", ErrParticipantReportV1
	}
	report, digest, err := ParseParticipantReportHTMLV3(claims.ParticipantReportHTML)
	if err != nil || report.Schema != claims.ParticipantReportSchema || report.DocumentID != claims.DocumentID || report.HistoryScope.OrgID != claims.OrgID || digest != claims.ParticipantReportSHA256 || report.Cutoff != claims.ParticipantReportCutoff || report.SourceRowsV2() != claims.ParticipantReportRows {
		return "", ErrParticipantReportV1
	}
	if strings.Contains(prefix, `<section class="hash-redaction-report">`) || (manifestHTML != nil && (len(*manifestHTML) == 0 || len(*manifestHTML) > MaxCertificatePayloadBytesV1 || strings.Contains(*manifestHTML, `<section class="hash-redaction-report">`))) {
		return "", ErrParticipantReportV1
	}
	// Claims HTML is fixed markup over a bounded closed scalar struct. Its
	// generated size is checked before appending into the complete bounded output.
	claimHTML := claims.HTML()
	write := func(w *participantHTMLWriterV3) {
		w.write(prefix)
		if err := certificateFieldsV2(w, fields); err != nil {
			w.err = err
			return
		}
		w.write(claimHTML)
		w.write(claims.ParticipantReportHTML)
		if manifestHTML != nil {
			w.write(*manifestHTML)
		}
	}
	measure := participantHTMLWriterV3{}
	write(&measure)
	if measure.err != nil {
		return "", errors.Join(ErrParticipantReportV1, measure.err)
	}
	var b strings.Builder
	b.Grow(measure.count)
	w := participantHTMLWriterV3{builder: &b}
	write(&w)
	if w.err != nil || w.count != measure.count {
		return "", ErrParticipantReportV1
	}
	return b.String(), nil
}

// Preserve V1's filled-field presentation, including its declared 200-rune
// summary, without creating an unrestricted []rune copy of an oversized value.
// Shared negotiation text in HTMLV3 is always complete, never summarized.
func certificateFieldsV2(w *participantHTMLWriterV3, rows []*generated.DocumentField) error {
	started := false
	for _, f := range rows {
		if w.err != nil {
			return w.err
		}
		if f == nil {
			return ErrParticipantReportV1
		}
		switch f.Type {
		case "text", "date", "checkbox", "dropdown", "initial":
		default:
			continue
		}
		if !f.Value.Valid || f.Value.String == "" {
			continue
		}
		label := ""
		if f.Label.Valid {
			label = f.Label.String
		}
		if !reportStringV2(label) {
			return ErrParticipantReportV1
		}
		if !started {
			w.write(`<h3 style="margin-top:24px">Filled fields</h3><table><thead><tr><th>Label</th><th>Type</th><th>Page</th><th>Value</th><th>Filled at</th></tr></thead><tbody>`)
			started = true
		}
		value := f.Value.String
		count := 0
		end := len(value)
		for i := range value {
			if count == 200 {
				end = i
				break
			}
			count++
		}
		if !reportStringV2(value[:end]) {
			return ErrParticipantReportV1
		}
		w.write("<tr><td>")
		w.text(label)
		w.write("</td><td>")
		w.text(f.Type)
		w.write("</td><td>")
		w.write(fmt.Sprint(f.Page))
		w.write("</td><td>")
		w.text(value[:end])
		if end < len(value) {
			w.text("… [truncated, full value in document_fields]")
		}
		w.write("</td><td>")
		w.text(certificateFormatNullableTSV2(f.CompletedAt))
		w.write("</td></tr>")
	}
	if started {
		w.write("</tbody></table>")
	}
	return w.err
}

// Absence is presentation, never an inferred signature or timestamp. Values
// that exist retain V1's exact escaping/hash/UTC formatting. Archived V1
// assembly deliberately continues to use its own byte-compatible helpers.
func certificateSignatureFontOrNAV2(s *generated.Signature) string {
	if s == nil {
		return "Not recorded"
	}
	return certificateSignatureFontOrNAV1(s)
}

func certificateSignatureSHAOrNAV2(s *generated.Signature) string {
	if s == nil {
		return "Not recorded"
	}
	return certificateSignatureSHAOrNAV1(s)
}

func certificateFormatNullableTSV2(t pgtype.Timestamptz) string {
	if !t.Valid {
		return "Not recorded"
	}
	return certificateFormatNullableTSV1(t)
}

func CertificateFinishV2(prefix string, doc *generated.Document, fields []*generated.DocumentField, claims CertificateEvidenceClaimsV1, manifestHTML *string, key *AuditCertificateKeyV1, orgName, baseURL string) (string, string, string, error) {
	payload, err := CertificatePayloadV2(prefix, doc, fields, claims, manifestHTML)
	if err != nil {
		return "", "", "", err
	}
	if key == nil || !reportStringV2(orgName) || !reportStringV2(baseURL) {
		return "", "", "", ErrParticipantReportV1
	}
	signature := key.SignPayload([]byte(payload))
	if signature == "" {
		return "", "", "", errors.New("audit certificate: signer returned an empty signature")
	}
	issuer := strings.TrimSpace(orgName)
	if issuer == "" {
		issuer = "Hash"
	}
	verifyURL := strings.TrimRight(strings.TrimSpace(baseURL), "/") + "/verify"
	write := func(w *participantHTMLWriterV3) {
		w.write(payload)
		w.write(`<div style="margin-top:24px;padding:12px;border:1px solid #ddd;background:#fafafa;font-family:monospace;font-size:9px;line-height:1.5;"><div><strong>Issuer:</strong> Hash / `)
		w.text(issuer)
		w.write(`</div><div><strong>Public key (ed25519, base64):</strong> `)
		w.text(key.PublicKeyBase64())
		w.write(`</div><div><strong>Signature (ed25519 over SHA-256(domain ‖ cert)):</strong> `)
		w.text(signature)
		w.write(`</div><div style="color:#666;margin-top:6px">Server-assisted verification (uploads certificate data): `)
		w.text(verifyURL)
		w.write(`</div></div></div>`)
	}
	measure := participantHTMLWriterV3{}
	write(&measure)
	if measure.err != nil {
		return "", "", "", measure.err
	}
	var b strings.Builder
	b.Grow(measure.count)
	w := participantHTMLWriterV3{builder: &b}
	write(&w)
	if w.err != nil || w.count != measure.count {
		return "", "", "", ErrParticipantReportV1
	}
	return b.String(), payload, signature, nil
}
